import {pathwaySubjects} from './pathway-entry-content.mjs';
import {pathwayView,rememberPathway,startPathwayPreview,choosePathwayPreview,showPathwayHelp,checkPathwayPreview,selectPathwayCheck,selectedPathwayCheck} from './pathway-entry-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(a,t,p=false)=>`<button type="button" class="${p?'primary':'secondary'}" ${a}>${esc(t)}</button>`;
const link=(g,label='Explore this')=>`<a class="secondary" href="${esc(g.route)}">${esc(label)}</a>`;
export const pathwayInvitation=()=>'<aside class="pathway-invitation"><h2>Choose a starting point by subject</h2><p>Explore a practical question or story in math, English, science or French. Each subject can have its own starting point.</p><a class="primary" href="#pathways">Choose a starting point</a></aside>';
function optionPicture(kind,key){if(kind!=='positions')return '';const x=key==='beside'?88:46,y=key==='on'?26:key==='under'?65:50;return `<svg viewBox="0 0 120 90" aria-hidden="true"><path d="M22 35H77M28 35V78M71 35V78" fill="none" stroke="#496c63" stroke-width="5"/><rect x="${x}" y="${y}" width="20" height="9" rx="2" fill="#c99148" stroke="#294e54"/></svg>`;}
function diagram(s){if(s.diagram==='height')return `<table class="pathway-height"><caption>${esc(s.model.caption)}</caption><thead><tr><th>x</th>${s.model.xs.map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody><tr><th>height</th>${s.model.ys.map(v=>`<td>${v}</td>`).join('')}</tr></tbody></table>`;if(s.diagram==='forces'){const l=135-s.model.left*13,r=205+s.model.right*13;return `<svg class="pathway-forces" viewBox="0 0 340 110" role="img" aria-label="One cart: ${s.model.left} newtons left and ${s.model.right} newtons right."><rect x="135" y="40" width="70" height="40" rx="8" fill="#d9b473" stroke="#294e54"/><circle cx="150" cy="86" r="9" fill="#294e54"/><circle cx="190" cy="86" r="9" fill="#294e54"/><path d="M135 55H${l}L${l+10} 45M${l} 55L${l+10} 65M205 55H${r}L${r-10} 45M${r} 55L${r-10} 65" fill="none" stroke="#294e54" stroke-width="4"/><text x="55" y="30">${s.model.left} N left</text><text x="222" y="30">${s.model.right} N right</text></svg>`;}return '';}
function historical(r,p){if(!r)return '';const french=r.source.subject==='french';return `<section class="pathway-result"><h3>Selected checked version</h3><p${french?' lang="fr"':''}>${esc(r.source.text)}</p><p${french?' lang="fr"':''}>${esc(r.source.prompt)}</p>${diagram(r.source)}<ol class="pathway-history-options">${r.source.options.map(o=>`<li${french?' lang="fr"':''}>${optionPicture(r.source.diagram,o.position)}${esc(o.text)}</li>`).join('')}</ol><p>Your choice: <strong>${esc(r.source.options.find(o=>o.id===r.raw)?.text||r.raw)}</strong>. ${r.outcome==='match'?'This choice fits the example.':'This example points to a different choice.'}</p><p${french?' lang="fr"':''}>${esc(r.feedback)}</p>${french&&p.help.meaning&&r.source.explanationMeaning?`<p lang="en">${esc(r.source.explanationMeaning)}</p>`:''}<p>Shown help before this check: ${Object.entries(r.helpBefore).filter(([,v])=>v).map(([k])=>esc(k)).join(', ')||'none requested'}.</p><div class="pathway-invitations">${r.source.routes.map(g=>`<article><h4>${esc(g.title)}</h4><p>${esc(g.purpose)}</p>${link(g)}</article>`).join('')}</div></section>`;}
function preview(p){const s=p.source,french=s.subject==='french',r=selectedPathwayCheck(p);return `<section class="pathway-preview"><h2 id="pathway-preview" tabindex="-1">${esc(s.title)}</h2><p${french?' lang="fr"':''}>${esc(s.text)}</p>${diagram(s)}<h3${french?' lang="fr"':''}>${esc(s.prompt)}</h3>${french?`<div class="pathway-actions">${btn('data-pathway-help="meaning"','Show English meaning')}${hearButton(`${s.text} ${s.prompt}`,'Écouter en français','fr')}</div>${p.help.meaning?`<aside class="pathway-help" lang="en"><p>${esc(s.meaning||'')}</p><p>${esc(s.promptMeaning||'')}</p><p>Sur = on · sous = under · à côté de = beside.</p></aside>`:''}`:''}<div class="pathway-options" role="group" aria-label="Answer choices">${s.options.map(o=>`<button type="button" class="secondary" data-pathway-choice="${esc(o.id)}" aria-pressed="${p.choice===o.id}"${french?' lang="fr"':''}>${optionPicture(s.diagram,o.position)}<span>${esc(o.text)}</span></button>`).join('')}</div><div class="pathway-actions">${btn('data-pathway-check','Check this example',true)}${btn('data-pathway-help="hint"','Show a hint')}<a href="${esc(s.routes[0].route)}">Skip for now and explore</a></div>${p.checks.length===4?'<p class="pathway-retention">The first check is kept. Checking again will replace the oldest of the four recent checks.</p>':''}${p.help.hint?`<aside class="pathway-help"><strong>Hint</strong><p${french?' lang="fr"':''}>${esc(s.hint)}</p>${french&&p.help.meaning?`<p lang="en">${esc(s.hintMeaning||'')}</p>`:''}</aside>`:''}${p.firstCheck||p.checks.length?`<label class="pathway-history">Choose a checked version<select data-pathway-version><option value="latest"${p.checkedView==='latest'?' selected':''}>Latest check</option>${p.firstCheck?`<option value="first"${p.checkedView==='first'?' selected':''}>First check</option>`:''}${p.checks.map((_,n)=>`<option value="${n}"${p.checkedView===n?' selected':''}>Recent check ${n+1}</option>`).join('')}</select></label>`:''}${historical(r,p)}</section>`;}
export function pathwayPage(state,subject='math'){const info=pathwaySubjects.find(s=>s.id===subject)||pathwaySubjects[0],v=pathwayView(state,info.id);return `<div class="pathway-page" data-pathway-root data-pathway-subject="${info.id}"><header><a href="#home">Back to the garden</a><p class="pathway-kicker">A place to begin</p><h1>Choose a starting point</h1><p>The town has questions and stories to investigate. Choose a place to contribute. You can choose another starting point any time.</p></header><nav class="pathway-subjects" aria-label="Subjects">${pathwaySubjects.map(s=>`<a class="secondary" href="#pathways/${s.id}"${s.id===info.id?' aria-current="page"':''}>${esc(s.title)}</a>`).join('')}</nav><h2 id="pathway-heading" tabindex="-1">${esc(info.title)}</h2>${v.status==='unavailable'||v.status==='unreadable'?'<p>Earlier starting-point records are retained. This version cannot edit them here. Direct exploration and notes remain available.</p>':''}${v.goal?`<aside class="pathway-remembered"><h3>Your remembered starting point: ${esc(v.goal.title)}</h3><p>${esc(v.goal.purpose)}</p>${link(v.goal,'Continue')}</aside>`:v.goalUnreadable?'<p>Your earlier goal is retained but cannot be read here. Your healthy optional example and direct exploration remain available.</p>':''}<div class="pathway-goals">${info.goals.map(g=>`<article><h3>${esc(g.title)}</h3><p>${esc(g.purpose)}</p><p class="pathway-challenge">Try thinking about: ${esc(g.challenge)}</p><div class="pathway-actions">${!['unavailable','unreadable'].includes(v.status)&&!v.goalUnreadable?btn(`data-pathway-remember="${g.id}" aria-pressed="${v.goal?.id===g.id}"`,'Remember this starting point'):''}${link(g)}</div></article>`).join('')}</div>${v.preview?preview(v.preview):v.previewUnreadable?'<section><h2>Earlier optional example retained</h2><p>It cannot be edited here; your goals and direct exploration are still available.</p></section>':!['unavailable','unreadable'].includes(v.status)?`<section class="pathway-preview"><h2>Try one small example (optional)</h2><p>You can use help or leave it. Your answer will not choose a starting point for you.</p>${btn('data-pathway-start','Start the optional example')}</section>`:''}<p id="pathway-status" role="status" aria-live="polite" tabindex="-1"></p><footer><a href="#begin">Café and reading amounts</a><a href="#notes">Grown-up notes</a></footer></div>`;}
export function pathwayNotes(state){if(!Object.hasOwn(state,'learningRoutes'))return '';return `<details class="panel"><summary>Subject starting points and optional examples</summary><p>Choices are separate by subject. Tiny examples suggest routes, not placement, ability, fluency or mastery. A remembered goal never changes automatically after an answer. First and four recent checked versions retain their own source, raw choice, requested support and outcome; French meaning/audio requests are support. Direct visits do not write preferences.</p>${pathwaySubjects.map(s=>{const v=pathwayView(state,s.id);return `<p>${esc(s.title)}: ${v.goal?esc(v.goal.title):'no readable remembered goal'}; ${v.preview?`${v.preview.checks.length} recent checks, first check ${v.preview.firstCheck?'kept':'not yet'}`:'no readable preview'}.</p>`;}).join('')}<details><summary>Exact saved sources, choices and support</summary><pre>${esc(JSON.stringify(state.learningRoutes,null,2))}</pre></details></details>`;}
export function bindPathways(state,{save,render,focus,canExport,explorerId,isActive}){const root=document.querySelector('[data-pathway-root]');if(!root)return;const subject=root.dataset.pathwaySubject,owner=explorerId?.(),route=location.hash,o={canExport};const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner;const say=(t,take=true)=>{const el=document.querySelector('#pathway-status');if(el){el.textContent=t;if(take)el.focus();}};const fail=()=>say('This change could not be kept safely. Earlier work is unchanged; download your notes or explore a destination.');const redraw=(t='',target='#pathway-heading')=>{stopSpeech();save();render();if(t){const el=document.querySelector('#pathway-status');if(el)el.textContent=t;}focus?.(target);};const clicks=(sel,fn)=>root.querySelectorAll(sel).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 root.addEventListener('click',e=>{const b=e.target.closest?.('[data-speak]');if(!b)return;if(!live(b)||!showPathwayHelp(state,subject,'audio',o)){e.preventDefault();e.stopImmediatePropagation();return fail();}save();},true);
 clicks('[data-pathway-remember]',b=>rememberPathway(state,subject,b.dataset.pathwayRemember,o)?redraw('Starting point remembered for this subject.','#pathway-status'):fail());
 clicks('[data-pathway-start]',()=>startPathwayPreview(state,subject,o)?redraw('Optional example opened.','#pathway-preview'):fail());
 clicks('[data-pathway-choice]',b=>choosePathwayPreview(state,subject,b.dataset.pathwayChoice,o)?redraw('Choice kept. You can change it before or after checking.',`[data-pathway-choice="${b.dataset.pathwayChoice}"]`):fail());
 clicks('[data-pathway-help]',b=>showPathwayHelp(state,subject,b.dataset.pathwayHelp,o)?redraw('Support opened.','#pathway-status'):fail());
 clicks('[data-pathway-check]',()=>{const r=checkPathwayPreview(state,subject,o);if(!r)return fail();if(!r.recorded)return say(r.feedback);redraw('Checked version kept. Explore either invitation, or choose any other goal.','#pathway-status');});
 root.querySelector('[data-pathway-version]')?.addEventListener('change',e=>{if(!live(e.target))return;const key=['first','latest'].includes(e.target.value)?e.target.value:Number(e.target.value);if(!selectPathwayCheck(state,subject,key,o))return fail();redraw('Earlier checked version selected.','[data-pathway-version]');});
}
